const getIssueBuildPRState = `-- name: GetIssueBuildPRState :one
WITH linked AS (
    SELECT pr.state
    FROM github_pull_request pr
    JOIN issue_pull_request ipr ON ipr.pull_request_id = pr.id
    WHERE ipr.issue_id = $1 AND NOT ipr.reference_only
    UNION ALL
    SELECT pr.state
    FROM vcs_pull_request pr
    JOIN issue_vcs_pull_request ipr ON ipr.pull_request_id = pr.id
    WHERE ipr.issue_id = $1 AND NOT ipr.reference_only
)
SELECT
    COUNT(*) FILTER (WHERE state IN ('open', 'draft'))::bigint AS open_count,
    COUNT(*) FILTER (WHERE state = 'merged')::bigint AS merged_count
FROM linked
`

type GetIssueBuildPRStateRow struct {
	OpenCount   int64 `json:"open_count"`
	MergedCount int64 `json:"merged_count"`
}

func (q *Queries) GetIssueBuildPRState(ctx context.Context, issueID pgtype.UUID) (GetIssueBuildPRStateRow, error) {
	row := q.db.QueryRow(ctx, getIssueBuildPRState, issueID)
	var i GetIssueBuildPRStateRow
	err := row.Scan(&i.OpenCount, &i.MergedCount)
	return i, err
}

const incrementIssueBuildAttempts = `-- name: IncrementIssueBuildAttempts :one
UPDATE issue
SET metadata = jsonb_set(
        metadata,
        '{build_attempts}',
        to_jsonb(
            CASE
                WHEN COALESCE(metadata->>'build_attempts', '') ~ '^[0-9]+$'
                    THEN (metadata->>'build_attempts')::integer + 1
                ELSE 1
            END
        ),
        true
    ),
    updated_at = now()
WHERE id = $1
RETURNING metadata
`

func (q *Queries) IncrementIssueBuildAttempts(ctx context.Context, id pgtype.UUID) ([]byte, error) {
	row := q.db.QueryRow(ctx, incrementIssueBuildAttempts, id)
	var metadata []byte
	err := row.Scan(&metadata)
	return metadata, err
}

