const moveIssueToHumanReviewUnlessInReview = `-- name: MoveIssueToHumanReviewUnlessInReview :one
UPDATE issue
SET status = CASE WHEN status = 'in_review' THEN status ELSE 'blocked' END,
    updated_at = now()
WHERE id = $1
RETURNING status
`

// The source vocabulary uses blocked; PPP's canonical-status trigger maps it
// to Human Review.  Never demote an issue that already reached in_review.
func (q *Queries) MoveIssueToHumanReviewUnlessInReview(ctx context.Context, id pgtype.UUID) (string, error) {
	row := q.db.QueryRow(ctx, moveIssueToHumanReviewUnlessInReview, id)
	var status string
	err := row.Scan(&status)
	return status, err
}

const reconcileIssueForExistingPR = `-- name: ReconcileIssueForExistingPR :one
UPDATE issue
SET status = CASE
        WHEN status IN ('done', 'cancelled') THEN status
        WHEN $1::boolean THEN 'done'
        ELSE 'in_review'
    END,
    updated_at = now()
WHERE id = $2
RETURNING id, workspace_id, title, description, status, priority, assignee_type, assignee_id, creator_type, creator_id, parent_issue_id, acceptance_criteria, context_refs, position, due_date, created_at, updated_at, number, project_id, origin_type, origin_id, first_executed_at, start_date, metadata, stage, properties, qc_fail_count
`

type ReconcileIssueForExistingPRParams struct {
	Merged  bool        `json:"merged"`
	IssueID pgtype.UUID `json:"issue_id"`
}

// Open work belongs in review; fully merged work is done.  Terminal issue
// states remain terminal and an in-review issue is never demoted to Queue.
func (q *Queries) ReconcileIssueForExistingPR(ctx context.Context, arg ReconcileIssueForExistingPRParams) (Issue, error) {
	row := q.db.QueryRow(ctx, reconcileIssueForExistingPR, arg.Merged, arg.IssueID)
	var i Issue
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Title,
		&i.Description,
		&i.Status,
		&i.Priority,
		&i.AssigneeType,
		&i.AssigneeID,
		&i.CreatorType,
		&i.CreatorID,
		&i.ParentIssueID,
		&i.AcceptanceCriteria,
		&i.ContextRefs,
		&i.Position,
		&i.DueDate,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Number,
		&i.ProjectID,
		&i.OriginType,
		&i.OriginID,
		&i.FirstExecutedAt,
		&i.StartDate,
		&i.Metadata,
		&i.Stage,
		&i.Properties,
		&i.QcFailCount,
	)
	return i, err
}
